import java.math.BigDecimal;
import org.springframework.transaction.annotation.Transactional;

// 使用Spring事务注解，保证操作原子性，出现任意异常自动回滚所有数据库操作
@Transactional(rollbackFor = Exception.class)
public Order processOrder(String userId, int buyCount, boolean useCoupon) {
    // 1. 参数校验（不涉及数据库操作，可放在事务外提前拦截非法参数）
    if (buyCount <= 0) {
        throw new IllegalArgumentException("购买数量不能小于等于0");
    }
    if (buyCount > 5) {
        throw new IllegalArgumentException("单次最多购买5件");
    }
    // 2. 原子性扣减库存：通过数据库update带条件，保证扣减的原子性，避免并发超卖
    // 返回值是更新的行数，若为0说明库存不足
    int updateCount = goodsDao.reduceStockWithCondition(10086, buyCount);
    if (updateCount == 0) {
        throw new BusinessException("库存不足");
    }
    // 3. 查询商品信息（获取单价）
    Goods goods = goodsDao.getGoodsById(10086);
    // 4. 使用BigDecimal计算金额，避免精度误差
    BigDecimal totalAmount = BigDecimal.valueOf(goods.getPrice())
            .multiply(BigDecimal.valueOf(buyCount));
    // 5. 优惠券校验：满100减10
    if (useCoupon && totalAmount.compareTo(BigDecimal.valueOf(100)) >= 0) {
        totalAmount = totalAmount.subtract(BigDecimal.valueOf(10));
    }
    // 6. 保存订单
    Order order = new Order();
    order.setUserId(userId);
    order.setGoodsId(10086);
    order.setBuyCount(buyCount);
    // 订单金额保留2位小数，存储为分单位可进一步避免精度问题（此处按业务要求存储为元）
    order.setTotalAmount(totalAmount);
    orderDao.saveOrder(order);
    return order;
}
// 对应DAO层扣减库存的SQL示例（MyBatis格式）：
// <update id="reduceStockWithCondition">
//     update goods set stock = stock - #{buyCount} where id = 10086 and stock >= #{buyCount}
// </update>
```
#### 修复方案说明
1. 库存校验与扣减合并为数据库原子操作，通过`update`语句的`where stock >= buyCount`条件保证只有库存足够时才扣减，同时避免并发超卖；
2. 添加`@Transactional`事务注解，任意环节抛出异常时自动回滚已执行的库存扣减操作，保证原子性；
3. 金额计算使用`BigDecimal`类型，避免`double`的精度误差；
4. 覆盖所有业务边界：参数校验拦截非法购买数，库存边界通过原子操作保证正确性，金额边界通过高精度计算保证准确。
#### 用户传入参数的修复后结果
用户传入`buyCount=5`、`useCoupon=true`时，修复后代码计算的订单金额为精确的`489.5`元，无精度误差，符合业务要求。

