@Service
public class SeckillStockService {
    @Autowired
    private UserBuyRecordMapper userBuyRecordMapper;
    @Autowired
    private StockMapper stockMapper;
    // 明确配置rollbackFor=Exception.class，确保所有异常（包括CheckedException）都触发回滚
    @Transactional(isolation = Isolation.REPEATABLE_READ, rollbackFor = Exception.class)
    public boolean deductStock(Long userId, Long skuId) {
        // 步骤1：直接插入用户购买记录，利用唯一约束防止重复购买，无需先查询
        try {
            UserBuyRecord record = new UserBuyRecord();
            record.setUserId(userId);
            record.setSkuId(skuId);
            userBuyRecordMapper.insert(record);
        } catch (DuplicateKeyException e) { // 唯一约束冲突，说明用户已购买过
            throw new BusinessException("您已购买过该商品，不可重复下单");
        }
        // 步骤2：原子扣减库存，判断影响行数
        int updateCount = stockMapper.deductStock(skuId);
        if (updateCount == 0) {
            throw new BusinessException("商品已售罄");
        }
        return true;
    }
}
